// ---------- the logbook: an Excel or CSV file read in the browser; only the counts per group leave it ----------
function rwLoadXlsx() { if (window.XLSX) return Promise.resolve(); return new Promise((ok, no) => { const s = document.createElement('script'); s.src = ['https:', '', 'cdnjs.cloudflare.com', 'ajax', 'libs', 'xlsx', '0.18.5', 'xlsx.full.min.js'].join('/'); s.onload = () => ok(); s.onerror = () => no(new Error('לא הצלחתי לטעון את קורא האקסל')); document.head.appendChild(s); }); }
function rwCsv(t) { const rows = []; let row = [], cur = '', q = false; for (let i = 0; i < t.length; i++) { const c = t[i]; if (q) { if (c === '"' && t[i + 1] === '"') { cur += '"'; i++; } else if (c === '"') q = false; else cur += c; } else if (c === '"') q = true; else if (c === ',' || c === '\t' || c === ';') { row.push(cur); cur = ''; } else if (c === '\n' || c === '\r') { if (c === '\r' && t[i + 1] === '\n') i++; row.push(cur); rows.push(row); row = []; cur = ''; } else cur += c; } if (cur || row.length) { row.push(cur); rows.push(row); } return rows; }
// which column is the procedure and which is the resident's role: by the header, otherwise the column with the longest text
function rwCount(rows) {
  rows = rows.filter(r => r && r.some(c => String(c || '').trim())); if (!rows.length) return null;
  const H = rows[0].map(c => String(c || '').trim()), hit = re => H.findIndex(h => re.test(h));
