    if (/לפרו|lap|robot|רובוט|TAPP|TEP/i.test(full)) out.lap++; const role = rc >= 0 ? String(r[rc] || '') : ''; const pri = /מלמד|teach/i.test(role) ? 2 : /ראשי|primary|^surgeon$|מנתח$|operator|מבצע/i.test(role.trim()) ? 1 : 0; if (pri === 2) out.teach++; if (pri) { out.primary++; if (g) out.np[g[0]] = (out.np[g[0]] || 0) + 1; } });
