const RK_ROLE = [['p', 'מנתח/ת ראשי/ת'], ['a', 'עוזר/ת'], ['t', 'מלמד/ת']], RK_AP = [['', 'לא צוין'], ['L', 'לפרוסקופי'], ['R', 'רובוטי'], ['O', 'פתוח']];
const RKS = { sel: '', role: 'p', ap: '', n: 1, d: '', only: 0, q: '', busy: 0 };
const rkMsg = s => (typeof toast === 'function' ? toast : typeof toast2 === 'function' ? toast2 : alert)(s);
const rkNow = () => (typeof TODAY !== 'undefined' ? TODAY : today);
// months since the start of the residency (a month string YYYY-MM)
function rkMonths(start) { if (!/^\d{4}-\d{2}$/.test(start || '')) return null; const [y, m] = start.split('-').map(Number), [ty, tm] = rkNow().split('-').map(Number); return Math.max(0, Math.min(72, (ty - y) * 12 + tm - m)); }
// the uploaded counts plus the manual entries: one logbook
function rkLog(R) {
  const L = (R && R.log) || {}, o = Object.assign({}, L, { n: Object.assign({}, L.n || {}), np: Object.assign({}, L.np || {}), primary: L.primary || 0, rows: L.rows || 0, other: L.other || 0, man: 0 });
  ((R && R.man) || []).forEach(e => { const k = e.n || 1; o.n[e.g] = (o.n[e.g] || 0) + k; o.rows += k; o.man += k; if (e.r === 'p' || e.r === 't') { o.primary += k; o.np[e.g] = (o.np[e.g] || 0) + k; } });
