}
// the forecast: linear by the pace so far; and what is needed per month to reach the targets by month 72
function rkFc(lg, mo) {
  const left = 72 - (mo || 0), pace = mo >= 3 ? lg.tot / mo : null, ppace = mo >= 3 ? lg.primary / mo : null;
  return { left, pace, proj: pace == null ? null : Math.round(lg.tot + pace * left), pproj: ppace == null ? null : Math.round(lg.primary + ppace * left),
    need: left > 0 ? Math.max(0, Math.ceil((RW_TOTAL - lg.tot) / left)) : 0, pneed: left > 0 ? Math.max(0, Math.ceil((RW_PRIMARY - lg.primary) / left)) : 0,
