  all('[data-rka]', b => b.onclick = () => { RKS.ap = b.dataset.rka; re(); });
  all('[data-rkn]', b => b.onclick = () => { RKS.n = Math.max(1, Math.min(20, RKS.n + +b.dataset.rkn)); re(); });
