  const go = q('#rkGo'); if (go) go.onclick = async () => { if (!RKS.sel || RKS.busy) return; RKS.busy = 1; go.disabled = true;
    try { await h.add([{ d: RKS.d || rkNow(), g: RKS.sel, r: RKS.role, a: RKS.ap, n: RKS.n }]); RKS.n = 1; RKS.sel = ''; } catch (e) { rkMsg(e.message || 'השמירה נכשלה'); } RKS.busy = 0; re(); };
