  inp.onchange = async () => { const f = inp.files[0]; if (!f) return; try { let rows;
      if (/\.(csv|txt)$/i.test(f.name)) rows = rwCsv(await f.text()); else { await rwLoadXlsx(); const wb = XLSX.read(await f.arrayBuffer(), { type: 'array' }); rows = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { header: 1, raw: false }); }
